from __future__ import annotations

import os
from dataclasses import dataclass
from functools import lru_cache
from typing import Any, Dict, Optional

import requests

from document_models import OCRResponse, normalize_ocr_response, normalize_ocr_text


@dataclass(frozen=True)
class OCRTranslationRequest:
    text: str
    target_language: str
    source_language: Optional[str] = None


@dataclass(frozen=True)
class OCRTranslationResponse:
    text: str
    source_language: Optional[str] = None
    target_language: Optional[str] = None
    raw: Any = None


@dataclass(frozen=True)
class AzureTranslatorConfig:
    endpoint: str
    key: Optional[str]
    region: Optional[str]
    api_version: str
    timeout: float


def _env(name: str, default: str = "") -> str:
    value = os.getenv(name)
    return value if value not in (None, "") else default


@lru_cache(maxsize=1)
def get_azure_translator_config() -> AzureTranslatorConfig:
    return AzureTranslatorConfig(
        endpoint=_env("AZURE_TRANSLATOR_ENDPOINT", "https://api.cognitive.microsofttranslator.com").rstrip("/"),
        key=os.getenv("AZURE_TRANSLATOR_KEY"),
        region=os.getenv("AZURE_TRANSLATOR_REGION"),
        api_version=_env("AZURE_TRANSLATOR_API_VERSION", "3.0"),
        timeout=float(_env("AZURE_TRANSLATOR_TIMEOUT", "60")),
    )


class AzureOCRTranslator:
    def __init__(self, config: Optional[AzureTranslatorConfig] = None) -> None:
        self.config = config or get_azure_translator_config()
        self._session = requests.Session()

    def translate_text(self, request: OCRTranslationRequest) -> OCRTranslationResponse:
        if not request.text:
            return OCRTranslationResponse(text="", source_language=request.source_language, target_language=request.target_language, raw={"translations": []})
        if not self.config.key:
            raise ValueError("Missing Azure Translator key")
        headers = {
            "Ocp-Apim-Subscription-Key": self.config.key,
            "Content-Type": "application/json; charset=utf-8",
        }
        if self.config.region:
            headers["Ocp-Apim-Subscription-Region"] = self.config.region
        params: Dict[str, str] = {"api-version": self.config.api_version, "to": request.target_language}
        if request.source_language:
            params["from"] = request.source_language
        body = [{"text": request.text}]
        response = self._session.post(f"{self.config.endpoint}/translate", params=params, json=body, headers=headers, timeout=self.config.timeout)
        response.raise_for_status()
        data = response.json()
        translated = ""
        if isinstance(data, list) and data:
            translations = data[0].get("translations", []) if isinstance(data[0], dict) else []
            if translations:
                translated = normalize_ocr_text(translations[0].get("text"))
        return OCRTranslationResponse(text=translated, source_language=request.source_language, target_language=request.target_language, raw=data)

    def translate_ocr_response(self, response: OCRResponse, target_language: str, source_language: Optional[str] = None) -> OCRTranslationResponse:
        normalized = normalize_ocr_response(response)
        return self.translate_text(OCRTranslationRequest(text=normalized.text, target_language=target_language, source_language=source_language or normalized.language))


def translate_ocr_text(text: str, target_language: str, source_language: Optional[str] = None, config: Optional[AzureTranslatorConfig] = None) -> OCRTranslationResponse:
    return AzureOCRTranslator(config=config).translate_text(OCRTranslationRequest(text=normalize_ocr_text(text), target_language=target_language, source_language=source_language))


def translate_ocr_response(response: OCRResponse, target_language: str, source_language: Optional[str] = None, config: Optional[AzureTranslatorConfig] = None) -> OCRTranslationResponse:
    return AzureOCRTranslator(config=config).translate_ocr_response(response, target_language=target_language, source_language=source_language)

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Dict, List, Optional, Tuple


class DocumentProcessingError(ValueError):
    pass


class ExtractionKind(str, Enum):
    OCR = "ocr"
    LAYOUT = "layout"


@dataclass(frozen=True)
class DocumentInput:
    content: bytes
    filename: Optional[str] = None
    content_type: Optional[str] = None


@dataclass(frozen=True)
class OCRRequest:
    document: DocumentInput
    language: Optional[str] = None
    include_confidence: bool = True


@dataclass(frozen=True)
class LayoutRequest:
    document: DocumentInput
    detect_tables: bool = True
    detect_blocks: bool = True
    detect_lines: bool = True


@dataclass(frozen=True)
class NormalizedSpan:
    text: str
    start: Optional[int] = None
    end: Optional[int] = None
    confidence: Optional[float] = None


@dataclass(frozen=True)
class BoundingBox:
    left: float
    top: float
    width: float
    height: float

    @property
    def right(self) -> float:
        return self.left + self.width

    @property
    def bottom(self) -> float:
        return self.top + self.height


@dataclass(frozen=True)
class OCRLine:
    text: str
    spans: Tuple[NormalizedSpan, ...] = ()
    confidence: Optional[float] = None
    bbox: Optional[BoundingBox] = None


@dataclass(frozen=True)
class OCRPage:
    page_number: int
    text: str
    lines: Tuple[OCRLine, ...] = ()
    confidence: Optional[float] = None


@dataclass(frozen=True)
class OCRResponse:
    text: str
    pages: Tuple[OCRPage, ...] = ()
    language: Optional[str] = None
    confidence: Optional[float] = None
    raw: Any = None


@dataclass(frozen=True)
class LayoutBlock:
    block_type: str
    text: str = ""
    bbox: Optional[BoundingBox] = None
    confidence: Optional[float] = None
    page_number: Optional[int] = None
    metadata: Dict[str, Any] = field(default_factory=dict)


@dataclass(frozen=True)
class LayoutTableCell:
    row_index: int
    column_index: int
    text: str
    bbox: Optional[BoundingBox] = None
    confidence: Optional[float] = None


@dataclass(frozen=True)
class LayoutTableRow:
    row_index: int
    cells: Tuple[LayoutTableCell, ...]


@dataclass(frozen=True)
class LayoutTable:
    rows: Tuple[LayoutTableRow, ...]
    bbox: Optional[BoundingBox] = None
    confidence: Optional[float] = None


@dataclass(frozen=True)
class LayoutResponse:
    blocks: Tuple[LayoutBlock, ...] = ()
    tables: Tuple[LayoutTable, ...] = ()
    raw: Any = None


def normalize_whitespace(text: Optional[str]) -> str:
    if not text:
        return ""
    return " ".join(text.replace("\u00a0", " ").split())


def normalize_ocr_text(text: Optional[str]) -> str:
    return normalize_whitespace(text)


def normalize_layout_text(text: Optional[str]) -> str:
    return normalize_whitespace(text)


def normalize_ocr_response(response: Any) -> OCRResponse:
    if isinstance(response, OCRResponse):
        return response
    if not isinstance(response, dict):
        raise DocumentProcessingError("OCR response must be a dict or OCRResponse")
    pages_data = response.get("pages") or []
    pages: List[OCRPage] = []
    for page in pages_data:
        lines: List[OCRLine] = []
        for line in page.get("lines", []) or []:
            spans = tuple(
                NormalizedSpan(
                    text=normalize_ocr_text(span.get("text")),
                    start=span.get("start"),
                    end=span.get("end"),
                    confidence=span.get("confidence"),
                )
                for span in line.get("spans", []) or []
            )
            bbox = line.get("bbox")
            lines.append(
                OCRLine(
                    text=normalize_ocr_text(line.get("text")),
                    spans=spans,
                    confidence=line.get("confidence"),
                    bbox=BoundingBox(**bbox) if isinstance(bbox, dict) else None,
                )
            )
        pages.append(
            OCRPage(
                page_number=int(page.get("page_number", 0)),
                text=normalize_ocr_text(page.get("text")),
                lines=tuple(lines),
                confidence=page.get("confidence"),
            )
        )
    return OCRResponse(
        text=normalize_ocr_text(response.get("text")),
        pages=tuple(pages),
        language=response.get("language"),
        confidence=response.get("confidence"),
        raw=response,
    )


def normalize_layout_response(response: Any) -> LayoutResponse:
    if isinstance(response, LayoutResponse):
        return response
    if not isinstance(response, dict):
        raise DocumentProcessingError("Layout response must be a dict or LayoutResponse")
    blocks: List[LayoutBlock] = []
    for block in response.get("blocks", []) or []:
        bbox = block.get("bbox")
        blocks.append(
            LayoutBlock(
                block_type=str(block.get("block_type", block.get("type", "unknown"))),
                text=normalize_layout_text(block.get("text")),
                bbox=BoundingBox(**bbox) if isinstance(bbox, dict) else None,
                confidence=block.get("confidence"),
                page_number=block.get("page_number"),
                metadata=dict(block.get("metadata") or {}),
            )
        )
    tables: List[LayoutTable] = []
    for table in response.get("tables", []) or []:
        rows: List[LayoutTableRow] = []
        for row in table.get("rows", []) or []:
            cells: List[LayoutTableCell] = []
            for cell in row.get("cells", []) or []:
                bbox = cell.get("bbox")
                cells.append(
                    LayoutTableCell(
                        row_index=int(cell.get("row_index", row.get("row_index", 0))),
                        column_index=int(cell.get("column_index", 0)),
                        text=normalize_layout_text(cell.get("text")),
                        bbox=BoundingBox(**bbox) if isinstance(bbox, dict) else None,
                        confidence=cell.get("confidence"),
                    )
                )
            rows.append(LayoutTableRow(row_index=int(row.get("row_index", 0)), cells=tuple(cells)))
        bbox = table.get("bbox")
        tables.append(
            LayoutTable(
                rows=tuple(rows),
                bbox=BoundingBox(**bbox) if isinstance(bbox, dict) else None,
                confidence=table.get("confidence"),
            )
        )
    return LayoutResponse(blocks=tuple(blocks), tables=tuple(tables), raw=response)


def build_ocr_request(content: bytes, filename: Optional[str] = None, content_type: Optional[str] = None, language: Optional[str] = None, include_confidence: bool = True) -> OCRRequest:
    return OCRRequest(document=DocumentInput(content=content, filename=filename, content_type=content_type), language=language, include_confidence=include_confidence)


def build_layout_request(content: bytes, filename: Optional[str] = None, content_type: Optional[str] = None, detect_tables: bool = True, detect_blocks: bool = True, detect_lines: bool = True) -> LayoutRequest:
    return LayoutRequest(document=DocumentInput(content=content, filename=filename, content_type=content_type), detect_tables=detect_tables, detect_blocks=detect_blocks, detect_lines=detect_lines)

